## 6️⃣ Quick “one‑file” starter

Create a file `src/initMap.js`:

```js
import * as maplibregl from 'maplibre-gl';
import * as pmtiles from 'pmtiles';
import 'maplibre-gl/dist/maplibre-gl.css';

// 1️⃣ Register protocol (run once)
const protocol = new pmtiles.Protocol();
maplibregl.addProtocol('pmtiles', protocol.tile);

// 2️⃣ Build the map
export function createMap(containerId) {
  return new maplibregl.Map({
    container: containerId,
    style: {
      version: 8,
      sources: {
        world: {
          type: 'vector',
          url: 'pmtiles://https://example.com/world.pmtiles'
        }
      },
      layers: [
        {
          id: 'land',
          type: 'fill',
          source: 'world',
          'source-layer': 'land',
          paint: { 'fill-color': '#eaeaea' }
        }
      ]
    },
    center: [0, 0],
    zoom: 2
  });
}
```

Then in your HTML:

```html
<div id="map" style="width:100%;height:100vh;"></div>
<script type="module">
  import { createMap } from './src/initMap.js';
  createMap('map');
</script>
```

That’s it – the map will fetch only the byte ranges it needs from `world.pmtiles`.

